export interface AIResponse {
  guidance: string;
  riskLevel: 'low' | 'medium' | 'high';
  riskScore: number;
  threatDetected: boolean;
  recommendedAction: 'sos' | 'contacts' | 'navigate_safe' | 'none';
  isLocal: boolean;
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
}

export function formatSafetyGuidance(guidance: string, riskLevel: 'low' | 'medium' | 'high'): string {
  let cleaned = guidance.trim();

  // Strip robotic prefix headers like "🔴 HIGH RISK", "🟡 MEDIUM RISK", "🟢 LOW RISK" if generated by model
  cleaned = cleaned.replace(/^(?:🔴|🟡|🟢)?\s*(?:HIGH|MEDIUM|LOW)\s+RISK\s*\n*/i, '').trim();

  return cleaned;
}

